// suspension
ctx.strokeStyle='#43515a';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-29,7);ctx.lineTo(-34,18);ctx.moveTo(29,7);ctx.lineTo(34,18);ctx.stroke();
// wheels
for(const wx of [-34,34]){ctx.fillStyle='#26343b';ctx.beginPath();ctx.arc(wx,18,wheelR,0,Math.PI*2);ctx.fill();ctx.fillStyle='#59676a';ctx.beginPath();ctx.arc(wx,18,8,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#9ca6a0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(wx-6,18);ctx.lineTo(wx+6,18);ctx.moveTo(wx,12);ctx.lineTo(wx,24);ctx.stroke()}
// car body
ctx.fillStyle='#d95339';roundRect(-45,-8,91,26,10);ctx.fill();ctx.fillStyle='#f47945';roundRect(-40,-12,78,19,8);ctx.fill();
// cab
ctx.fillStyle='#f6b84a';ctx.beginPath();ctx.moveTo(-18,-12);ctx.lineTo(-8,-30);ctx.quadraticCurveTo(0,-37,17,-29);ctx.lineTo(28,-12);ctx.closePath();ctx.fill();ctx.strokeStyle='#b84b35';ctx.lineWidth=3;ctx.stroke();
ctx.fillStyle='#a6e2dc';ctx.beginPath();ctx.moveTo(-8,-28);ctx.quadraticCurveTo(0,-34,11,-28);ctx.lineTo(17,-15);ctx.lineTo(-16,-15);ctx.closePath();ctx.fill();ctx.strokeStyle='#fce7ac';ctx.lineWidth=2;ctx.stroke();
// driver
ctx.fillStyle='#394e55';ctx.beginPath();ctx.arc(0,-23,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f7d286';ctx.beginPath();ctx.arc(1,-26,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#43535a';ctx.beginPath();ctx.arc(1,-28,5,Math.PI,Math.PI*2);ctx.fill();
ctx.fillStyle='#ffe477';ctx.beginPath();ctx.arc(43,1,4,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawFuel(){for(let i=1;i<=8;i++){const x=620+i*740;if(x<camX-50||x>camX+W+50)continue;const y=groundY(x)-35;ctx.save();ctx.translate(x-camX,y);ctx.fillStyle='#d94e39';roundRect(-11,-15,22,29,5);ctx.fill();ctx.fillStyle='#ffd459';roundRect(-7,-12,14,20,3);ctx.fill();ctx.fillStyle='#d94e39';ctx.fillRect(-6,-19,12,5);ctx.fillStyle='#fff';ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.fillText('F',0,3);ctx.restore()}}
function drawDecor(){// roadside pines
for(let i=0;i<8;i++){let wx=i*360+180;let sx=wx-camX*.72;if(sx<-40||sx>W+40)continue;let y=groundY(wx)-12;ctx.fillStyle='#946c46';ctx.fillRect(sx-4,y-31,8,32);ctx.fillStyle=i%2?'#4e9a62':'#4c9567';ctx.beginPath();ctx.moveTo(sx,y-78);ctx.lineTo(sx-27,y-27);ctx.lineTo(sx+27,y-27);ctx.closePath();ctx.fill();ctx.fillStyle='#68b873';ctx.beginPath();ctx.moveTo(sx,y-60);ctx.lineTo(sx-20,y-25);ctx.lineTo(sx+20,y-25);ctx.closePath();ctx.fill()}}
function draw(){ctx.clearRect(0,0,W,H);drawSky();drawDecor();drawTerrain();drawFuel();const startN=Math.max(0,Math.floor((camX-300)/205)),endN=Math.ceil((camX+W+300)/205);for(let n=startN;n<=endN;n++)drawCoin(coinAt(n),n);drawCar();if(state==='menu'){// menu still shows car on a gentle slope
}for(const p of particles){ctx.globalAlpha=p.life;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x-camX,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function puff(x,y,color){for(let i=0;i<7;i++)particles.push({x,y,vx:(Math.random()-.5)*95,vy:-Math.random()*90,life:.55,color,r:2+Math.random()*4})}
function finish(reason){state='over';held.gas=held.brake=false;best=Math.max(best,Math.floor(worldX/10));localStorage.setItem('hillclimb-best',best);$('overlay').classList.remove('hidden');$('overlay').innerHTML=`<div class="card"><div class="eyebrow">${reason==='fuel'?'OUT OF GAS!':'THAT WAS A GOOD RUN!'}</div><h1>RUN<br><em>COMPLETE</em></h1><p class="result">🏁 ${Math.floor(worldX/10)} m &nbsp; · &nbsp; 🪙 ${coinCount}</p><p>Best distance: ${best} m<br>${reason==='fuel'?'Your engine sputtered out.':'The buggy took a tumble!'}</p><button class="play" id="playAgain">RACE AGAIN&nbsp; ↗</button><p class="tips">TOUCH THE PEDALS OR USE ← → / A D</p></div>`;document.getElementById('playAgain').addEventListener('click',start)}
function update(dt){if(state!=='play')return;dt=Math.min(dt,.035);let throttle=(held.gas?1:0)-(held.brake?1:0);let ground=groundY(worldX);const wheelGround=Math.min(groundY(worldX-34*Math.cos(angle)),groundY(worldX+34*Math.cos(angle)));
// Engine, gravity, and simple hill-following suspension
if(held.gas&&fuel>0){speed+=250*dt;fuel-=1.5*dt}else if(held.brake)speed-=240*dt;else speed-=22*dt;
speed=clamp(speed,0,430);let slope=Math.atan2(groundY(worldX+18)-groundY(worldX-18),36);
const airborne=carY+35<wheelGround;
if(airborne){airtime+=dt;vy+=720*dt;carY+=vy*dt;angVel+=throttle*2.7*dt;angle+=angVel*dt}else{if(airtime>.25){puff(worldX,carY+25,'#e8c879');airtime=0}carY=lerp(carY,wheelGround-37,Math.min(1,dt*22));vy=0;angle=lerp(angle,slope,Math.min(1,dt*6));angVel*=.86;if(speed>75&&Math.random()<dt*2)puff(worldX-30,groundY(worldX),'#d7bd85')}
// move based on power and terrain
worldX+=speed*dt;camX=lerp(camX,Math.max(0,worldX-W*.34),Math.min(1,dt*4));fuel=clamp(fuel,0,100);maxDist=Math.max(maxDist,worldX);
let n=Math.round((worldX-280)/205);for(let k=n-1;k<=n+1;k++){if(k>=0&&!collected.has(k)){let c=coinAt(k);if(Math.hypot(c.x-worldX,c.y-(carY-5))<45){collected.add(k);coinCount+=1;fuel=clamp(fuel+1.5,0,100);puff(c.x,c.y,'#ffd957')}}}
for(let i=1;i<=8;i++){let fx=620+i*740;if(Math.abs(fx-worldX)<35&&fuel<100){fuel=clamp(fuel+42,0,100);puff(fx,groundY(fx)-25,'#f77b4a')}}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=140*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);
const upside=Math.abs(angle)>2.35;if(upside&& !airborne){shake+=dt;if(shake>1.0){finish('crash');return}}else shake=0;
if(fuel<=0&&speed<35){finish('fuel');return}
$('coins').textContent=coinCount;$('distance').textContent=Math.floor(worldX/10)+' m';$('fuelText').textContent=Math.ceil(fuel)+'%';$('fuelBar').style.width=fuel+'%';$('fuelBar').style.background=fuel<25?'#ed6549':fuel<50?'#f2b548':'#79c957';$('status').textContent=airborne?'AIR TIME!  •  BALANCE WITH THE PEDALS':speed>290?'FULL THROTTLE!':'HOLD ▲ TO GO • ▼ TO BRAKE';}
function loop(now){let dt=(now-last)/1000||0;last=now;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
})();
</script></body></html>

