const { createRequire } = require('node:module');
const runtimeRequire = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = runtimeRequire('playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  const errors = [], failed = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('response', r => { if (r.status() >= 400) failed.push(`${r.status()} ${r.url()}`); });
  const response = await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.locator('#play').click();
  await page.locator('#gas').dispatchEvent('pointerdown', { pointerId: 1, pointerType: 'touch', isPrimary: true, button: 0, buttons: 1, clientX: 330, clientY: 760 });
  await page.waitForTimeout(1000);
  await page.locator('#gas').dispatchEvent('pointerup', { pointerId: 1, pointerType: 'touch', isPrimary: true, button: 0, buttons: 0, clientX: 330, clientY: 760 });
  await page.waitForTimeout(300);
  const metrics = await page.evaluate(() => {
    const box = s => { const r = document.querySelector(s).getBoundingClientRect(); return { x:r.x,y:r.y,width:r.width,height:r.height,bottom:r.bottom,right:r.right }; };
    const status=box('#status'), bounds=box('.stats');
    const overlap = status.x < bounds.right && status.right > bounds.x && status.y < bounds.bottom && status.bottom > bounds.y;
    return { viewport:{width:innerWidth,height:innerHeight}, distance:document.querySelector('#dist').textContent, fuel:document.querySelector('#fuelText').textContent, statusOverlapsStats:overlap, brake:box('#brake'), gas:box('#gas') };
  });
  await page.screenshot({ path: '/tmp/opencode/hill-climb-mobile.jpg', type: 'jpeg', quality: 78 });
  console.log(JSON.stringify({ http:response.status(), title:await page.title(), metrics, errors, failed }, null, 2));
  await browser.close();
})();
